using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using LWS.TruckSports;using LWS.TruckSports.Editor;
namespace LWS.TruckLimbo.Editor {
public static class LimboReviewAuthoring {
 public static void Upgrade(){EditorSceneManager.OpenScene(LimboAuthoring.Scene);var m=UnityEngine.Object.FindAnyObjectByType<LimboMatch>();Install(m);EditorSceneManager.SaveScene(m.gameObject.scene);AssetDatabase.SaveAssets();LimboAuthoring.Validate();}
 public static void Install(LimboMatch match){LimboVenueAuthoring.Install(match);var audience=match.GetComponent<LimboAudience>();if(audience!=null){var controller=SportsAudienceAuthoring.DanceController("TruckLimbo");foreach(var actor in audience.actors)if(actor!=null){actor.runtimeAnimatorController=controller;actor.enabled=true;EditorUtility.SetDirty(actor);}}var review=match.GetComponent<LimboReview>();if(review==null){review=match.gameObject.AddComponent<LimboReview>();review.match=match;var sources=new Transform[16];for(int i=0;i<8;i++){sources[i*2]=match.racers[i].transform;sources[i*2+1]=match.racers[i].bar.transform;}review.motion=SportsRallyAuthoring.Replay(match,sources);review.motion.capacity=900;review.motion.interval=.05f;review.motion.maximumReplayAge=35;foreach(var ghost in review.motion.ghosts)if(ghost.GetComponentsInChildren<Rigidbody>(true).Length>0||ghost.GetComponentsInChildren<Collider>(true).Length>0)throw new InvalidOperationException("Limbo review must not resimulate collisions.");}match.review=review;var cameras=match.views.views.Select(v=>v.view).Concat(new[]{match.views.broadcast.view}).ToArray();SportsWeatherRenderingAuthoring.Install(match.gameObject,cameras,"TruckLimbo");SportsScenicGradeAuthoring.Install(match.gameObject,cameras,"TruckLimbo",-.65f);if(Array.TrueForAll(match.menus.pages[6].GetComponentsInChildren<SportsMenuAction>(true),a=>a.action!="limboreview"))SportsUIAuthoring.Button(match.menus.pages[6].transform,"WATCH FINAL BAR","limboreview",new Vector2(0,-240),new Vector2(440,58));EditorUtility.SetDirty(review);EditorUtility.SetDirty(match);}
}
}
